use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // To minimize memory usage, build the hash set on the smaller vector
    if a.len() <= b.len() {
        let set: HashSet<i32> = a.into_iter().collect();
        for x in b {
            if set.contains(&x) {
                return true;
            }
        }
    } else {
        let set: HashSet<i32> = b.into_iter().collect();
        for x in a {
            if set.contains(&x) {
                return true;
            }
        }
    }
    false
}

